package io.zem.ibox;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.*;import java.io.*;import java.util.function.BooleanSupplier;
final class StorageLocation {
    static final int PICK_FOLDER=81,IMPORT=82;
    static Uri tree(Context c){String value=c.getSharedPreferences("storage",0).getString("tree","");return value.isEmpty()?null:Uri.parse(value);}
    static String label(Context c){Uri tree=tree(c);if(tree==null)return "Download/Zem iBox Drive";try{Uri root=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));try(Cursor cursor=c.getContentResolver().query(root,new String[]{DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())return cursor.getString(0);}}catch(Exception ignored){}return "Выбранная папка недоступна";}
    static void select(Context c,Uri uri,int flags){int access=flags&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);if((access&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)==0)throw new SecurityException("Папка должна разрешать сохранение файлов");c.getContentResolver().takePersistableUriPermission(uri,access);c.getSharedPreferences("storage",0).edit().putString("tree",uri.toString()).apply();}
    static void reset(Context c){Uri old=tree(c);c.getSharedPreferences("storage",0).edit().remove("tree").apply();if(old!=null)try{c.getContentResolver().releasePersistableUriPermission(old,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(SecurityException ignored){}}
    static Uri publish(Context c,File file,String name,String mime,String camera,BooleanSupplier cancelled)throws Exception{
        Uri tree=tree(c),folder=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));ContentResolver resolver=c.getContentResolver();
        for(String segment:camera.split("/")){if(segment.isEmpty())continue;if(segment.equals(".")||segment.equals(".."))throw new IOException("Неверное имя папки");Uri next=null,children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getDocumentId(folder));try(Cursor cursor=resolver.query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE},null,null,null)){if(cursor!=null)while(cursor.moveToNext())if(segment.equals(cursor.getString(1))&&DocumentsContract.Document.MIME_TYPE_DIR.equals(cursor.getString(2))){next=DocumentsContract.buildDocumentUriUsingTree(tree,cursor.getString(0));break;}}if(next==null)next=DocumentsContract.createDocument(resolver,folder,DocumentsContract.Document.MIME_TYPE_DIR,segment);if(next==null)throw new IOException("Не удалось создать папку");folder=next;}
        Uri target=DocumentsContract.createDocument(resolver,folder,mime,new File(name).getName());if(target==null)throw new IOException("Не удалось создать файл в выбранной папке");boolean success=false;
        try{try(InputStream in=new FileInputStream(file);OutputStream out=resolver.openOutputStream(target,"w")){if(out==null)throw new IOException("Нет доступа к папке сохранения");byte[] block=new byte[128*1024];int n;while((n=in.read(block))!=-1){if(cancelled.getAsBoolean())throw new InterruptedIOException("Сохранение отменено");out.write(block,0,n);}if(cancelled.getAsBoolean())throw new InterruptedIOException("Сохранение отменено");}success=true;return target;}finally{if(!success)try{DocumentsContract.deleteDocument(resolver,target);}catch(Exception ignored){}}
    }
    static void importFile(Context c,Uri uri,int flags)throws Exception{
        if(!"content".equals(uri.getScheme()))throw new IOException("Выберите файл через системное окно");if((flags&Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION)!=0)c.getContentResolver().takePersistableUriPermission(uri,flags&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));
        String name="Видео",mime=c.getContentResolver().getType(uri);long size=0;try(Cursor cursor=c.getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(cursor!=null&&cursor.moveToFirst()){name=cursor.getString(0);size=cursor.getLong(1);}}
        if(mime==null||(!mime.startsWith("video/")&&!mime.startsWith("image/")))throw new IOException("Можно добавить только фото и видео");Library.requireReadable(c,uri);org.json.JSONArray all=Library.all(c);for(int i=0;i<all.length();i++)if(uri.toString().equals(all.getJSONObject(i).optString("uri")))return;Library.add(c,uri,name,mime,size,"import");
    }
}
